package com.anksoft.myapplication.core.storage

import java.security.GeneralSecurityException
import java.security.ProviderException
import javax.crypto.Cipher
import javax.crypto.spec.GCMParameterSpec
import kotlin.io.encoding.Base64

/**
 * AES-256-GCM over a key from [keys]. The stored form is `Base64(IV || ciphertext || tag)`.
 *
 * The IV is always generated by the [Cipher] (the Android Keystore refuses caller-supplied IVs for
 * encryption), so it is fresh for every call. There is no code path that returns or stores the
 * plaintext when encryption fails: every failure surfaces as [SessionCipherException].
 */
internal class AesGcmSessionCipher(private val keys: SecretKeyProvider) : SessionCipher {

    override fun encrypt(plaintext: String, associatedData: String): String = guarded {
        val cipher = Cipher.getInstance(TRANSFORMATION)
        cipher.init(Cipher.ENCRYPT_MODE, keys.getOrCreate())
        cipher.updateAAD(associatedData.encodeToByteArray())
        val encrypted = cipher.doFinal(plaintext.encodeToByteArray())
        val iv = cipher.iv
        if (iv == null || iv.size != IV_BYTES) throw SessionCipherException()
        Base64.Default.encode(iv + encrypted)
    }

    override fun decrypt(encoded: String, associatedData: String): String = guarded {
        // A missing key must not be replaced by a new one: old data would silently stay unreadable.
        val key = keys.existing() ?: throw SessionCipherException()
        val bytes = Base64.Default.decode(encoded)
        if (bytes.size < IV_BYTES + TAG_BYTES) throw SessionCipherException()
        val cipher = Cipher.getInstance(TRANSFORMATION)
        cipher.init(Cipher.DECRYPT_MODE, key, GCMParameterSpec(TAG_BITS, bytes, 0, IV_BYTES))
        cipher.updateAAD(associatedData.encodeToByteArray())
        cipher.doFinal(bytes, IV_BYTES, bytes.size - IV_BYTES).decodeToString()
    }

    override fun deleteKey() {
        guarded { keys.delete() }
    }

    private inline fun <T> guarded(block: () -> T): T = try {
        block()
    } catch (e: SessionCipherException) {
        throw e
    } catch (e: GeneralSecurityException) {
        throw SessionCipherException(e)
    } catch (e: ProviderException) {
        throw SessionCipherException(e)
    } catch (e: IllegalArgumentException) {
        throw SessionCipherException(e)
    }

    private companion object {
        const val TRANSFORMATION = "AES/GCM/NoPadding"
        const val IV_BYTES = 12
        const val TAG_BITS = 128
        const val TAG_BYTES = TAG_BITS / 8
    }
}
